/** The command ran and said no: exit 1, so scripts and CI do not read a refusal as success. */
function refuse(msg) {
	console.error(msg);
	process.exitCode = 1;
}
function fail(msg) {
	console.error(msg);
	process.exit(2);
}
main().catch((e) => {
	console.error(String(e?.message ?? e));
	process.exit(1);
});
export {};
